# producer (network)
resource "aws_ssm_parameter" "vpc_id" {
  name  = "/prod/network/vpc_id"
  type  = "String"
  value = aws_vpc.main.id
}
# consumer (app)
data "aws_ssm_parameter" "vpc_id" { name = "/prod/network/vpc_id" }
locals { vpc_id = data.aws_ssm_parameter.vpc_id.value }

import {
  to = aws_s3_bucket.logs
  id = "acme-legacy-logs"
}
# terraform plan -generate-config-out=generated.tf
# refine generated.tf, then plan until: 0 to add, 0 to change, 0 to destroy (1 to import)

moved {
  from = aws_db_instance.main
  to   = module.database.aws_db_instance.this
}
# plan: module.database.aws_db_instance.this has moved to ...
# Plan: 0 to add, 0 to change, 0 to destroy.

resource "aws_db_instance" "main" {
  engine                      = "postgres"
  instance_class              = "db.r6g.large"
  username                    = "app"
  manage_master_user_password = true   # stored in Secrets Manager, not state
}
